arguments.command:
cat > /tmp/git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) printf '%s\n' 'x-access-token' ;;
*) printf '%s\n' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/git-askpass.sh
GIT_ASKPASS=/tmp/git-askpass.sh git -C /tmp/friends-rachel-wt push origin HEAD:refs/heads/friend/rachel
